<script setup lang="ts">
import { computed, ref, watch } from "vue";
import UButton from "@nuxt/ui/components/Button.vue";
import UInput from "@nuxt/ui/components/Input.vue";
import USelect from "@nuxt/ui/components/Select.vue";
import UModal from "@nuxt/ui/components/Modal.vue";
import UIcon from "@nuxt/ui/components/Icon.vue";
import UCheckbox from "@nuxt/ui/components/Checkbox.vue";
import { sourceFor, sourceLabel } from "@/domain/sources";
import { fileFilters, matchesFilter } from "@/lib/organizer";
import { pickFolder } from "@/lib/tauri";
import { addCustomGroup, addFolderMapping, assignGroupToTabs, createCategoryView, createTabGroup, executeOrganization,
  itemsByPanel, locateSurface, mappingErrors, moveTab, operationResults, rebindMapping, removeCustomGroup, removeTabGroup,
  renameCustomGroup, renameTabGroup, scheduleSave, setPanelVisible, showStatus, store, updateGroupView } from "@/stores/state";
import type { CustomGroupDefinition } from "@/types";
import { fileMoves, openMoveResults } from '@/composables/fileMoveReports';
const props = defineProps<{ initialId?: string; addSignal?: number; initialKind?: 'zone'|'folder' }>();
const filter = ref("all"), creating = ref(false), createOpen = ref(false), kind = ref(""), name = ref(""), path = ref("");
const typeFilter = ref<CustomGroupDefinition['filter']>("documents"), selectedSources = ref<string[]>([]);
const detailId = ref(""), detailName = ref(""), detailOpen = ref(false), error = ref("");
const detail = computed(()=>store.customGroups.find(group=>group.id===detailId.value));
const groups = computed(()=>store.customGroups.filter(group=>filter.value==="all"||sourceFor(group).kind===filter.value));
const typeOptions = [{label:"全部类型",value:"all"},{label:"收纳区",value:"zone"},{label:"文件夹映射",value:"folder"},{label:"分类视图",value:"category"}];
const kinds = [{id:"zone",name:"新建收纳区",icon:"i-lucide-folder-plus",description:"创建真实目录，拖入会移动文件"},{id:"folder",name:"显示已有文件夹",icon:"i-lucide-folder-open",description:"默认只浏览，原文件位置不变"},{id:"category",name:"按类型查看桌面",icon:"i-lucide-list-filter",description:"只改变显示范围，不移动文件"},{id:"group",name:"组合多个来源",icon:"i-lucide-panels-top-left",description:"以文件组标签页访问多个来源"}];
function add() { createOpen.value=true; kind.value=""; name.value=""; path.value=""; error.value=""; selectedSources.value=[]; }
watch(()=>props.addSignal,signal=>{if(signal){add();kind.value=props.initialKind??'';}},{immediate:true});
watch(()=>props.initialId,id=>{ if(id)openDetail(id); },{immediate:true});
function openDetail(id:string){detailId.value=id;detailName.value=store.customGroups.find(g=>g.id===id)?.name??"";detailOpen.value=true;error.value="";}
async function browse(){try{path.value=await pickFolder()??path.value;if(!name.value)name.value=path.value.split(/[\\/]/).pop()??"";}catch(e){error.value=String(e)}}
async function submit(){if(!name.value.trim()||creating.value)return;creating.value=true;error.value="";try{
  let success=true;
  if(kind.value==='zone')success=await addCustomGroup(name.value.trim());
  if(kind.value==='folder')success=await addFolderMapping(name.value.trim(),path.value);
  if(kind.value==='category')createCategoryView(name.value.trim(),typeFilter.value);
  if(kind.value==='group'){const id=createTabGroup(name.value.trim());for(const source of selectedSources.value)assignGroupToTabs(source,id);}
  if(success)createOpen.value=false;else error.value=store.statusMessage;
}catch(e){error.value=String(e)}finally{creating.value=false}}
async function saveName(){await renameCustomGroup(detailId.value,detailName.value);}
async function repair(id:string){try{const p=await pickFolder();if(p)await rebindMapping(id,p)}catch(e){showStatus(`无法重绑：${e}`)}}
function surfaceKey(id:string){const tabs=store.tabGroups.find(t=>t.groupIds.includes(id));return tabs?`tabs:${tabs.id}`:`zone:${id}`}
function membership(groupId:string){return store.tabGroups.find(t=>t.groupIds.includes(groupId))?.id??"__standalone"}
const ruleOpen = ref(false), ruleSource = ref("desktop"), ruleTarget = ref(""), ruleFilter = ref<CustomGroupDefinition['filter']>("documents"), ruleQuery=ref("");
const previewTarget=ref("");
const plan=ref<{id:string;path:string;name:string}[]>([]), executing=ref(false);
const targetOptions=computed(()=>store.customGroups.filter(g=>sourceFor(g).kind==='zone').map(g=>({label:g.name,value:g.id})));
const sourceOptions=computed(()=>[{label:'个人桌面',value:'desktop'},...store.customGroups.filter(g=>sourceFor(g).kind==='zone').map(g=>({label:g.name,value:g.id}))]);
const target=computed(()=>store.customGroups.find(g=>g.id===ruleTarget.value));
watch([ruleSource,ruleTarget,ruleFilter,ruleQuery],()=>{plan.value=[]});
function preview(){previewTarget.value=target.value?.dirName??"";operationResults.splice(0);const entries=ruleSource.value==='desktop'?store.entries.filter(e=>e.canManage&&!e.zone):(itemsByPanel.value[`zone:${ruleSource.value}`]??[]);plan.value=entries.filter(e=>e.canManage&&!e.isHidden&&matchesFilter(e,ruleFilter.value)&&e.name.toLowerCase().includes(ruleQuery.value.trim().toLowerCase())).map(e=>({id:e.id,path:e.path,name:e.name}));}
async function execute(retry=false){if(executing.value)return;if(target.value?.dirName!==previewTarget.value){plan.value=[];showStatus("目标目录在预览后发生变化，请重新生成预览");return;}executing.value=true;try{const entries=retry?plan.value.filter(item=>operationResults.some(result=>!result.ok&&result.path===item.path)):plan.value;await executeOrganization(entries,ruleTarget.value);}finally{executing.value=false}}
const groupOptions=computed(()=>[{label:'独立面板',value:'__standalone'},...store.tabGroups.map(t=>({label:t.name,value:t.id}))]);
</script>
<template>
  <div class="page-heading"><div><h1>文件与收纳</h1><p>按来源组织文件，让每次移动都有明确目标。</p></div><UButton icon="i-lucide-plus" @click="add">添加桌面内容</UButton></div>
  <div class="page-toolbar"><USelect v-model="filter" :items="typeOptions" aria-label="来源类型"/><UButton variant="outline" icon="i-lucide-list-checks" @click="ruleOpen=true">整理预览</UButton><UButton v-if="fileMoves.reports.length" variant="outline" @click="openMoveResults">本次整理结果</UButton></div>
  <div class="manager-card"><div class="card-heading"><h2>文件来源与视图</h2><span>{{groups.length}} 个</span></div>
    <div v-for="group in groups" :key="group.id" class="source-row"><div class="source-icon"><UIcon :name="group.sourceKind==='category'?'i-lucide-list-filter':group.mappedPath?'i-lucide-folder-open':'i-lucide-folder'"/></div><div class="row-content"><strong>{{group.name}}</strong><small>{{group.sourceKind==='category'?'个人桌面 · 分类视图':group.mappedPath??`桌面\\.nestra\\${group.dirName}`}}</small><p v-if="mappingErrors[group.id]" class="error-text">{{mappingErrors[group.id]}}</p></div><span class="source-badge">{{sourceLabel(group)}}</span><span class="count-text">{{itemsByPanel[`zone:${group.id}`]?.length??0}} 项</span><UButton size="sm" variant="ghost" color="neutral" @click="setPanelVisible(surfaceKey(group.id),store.panelLayouts[surfaceKey(group.id)]?.visible===false)">{{store.panelLayouts[surfaceKey(group.id)]?.visible===false?'显示':'隐藏'}}</UButton><UButton size="sm" variant="outline" @click="openDetail(group.id)">管理</UButton></div>
    <div v-if="!groups.length" class="manager-empty"><UIcon name="i-lucide-folder-plus"/><h3>从一个文件来源开始</h3><p>新建收纳区，或把已有文件夹显示到桌面。</p><UButton variant="outline" @click="add">添加桌面内容</UButton></div>
  </div>
  <div class="manager-card"><div class="card-heading"><h2>文件组</h2><span>组合来源，不移动文件</span></div><div v-for="tabs in store.tabGroups" :key="tabs.id" class="file-group"><div class="settings-row"><UInput :model-value="tabs.name" aria-label="文件组名称" @change="renameTabGroup(tabs.id,($event.target as HTMLInputElement).value)"/><div class="flex gap-2"><UButton variant="ghost" size="sm" @click="locateSurface(`tabs:${tabs.id}`)">显示并定位</UButton><UButton variant="ghost" size="sm" color="error" @click="removeTabGroup(tabs.id)">解散文件组</UButton></div></div><div class="source-chips"><span v-for="(id,index) in tabs.groupIds" :key="id" class="source-chip">{{store.customGroups.find(g=>g.id===id)?.name}}<button :disabled="index===0" aria-label="来源左移" @click="moveTab(tabs.id,id,-1)">←</button><button :disabled="index===tabs.groupIds.length-1" aria-label="来源右移" @click="moveTab(tabs.id,id,1)">→</button><button aria-label="移出文件组" @click="assignGroupToTabs(id,null)">×</button></span><span v-if="!tabs.groupIds.length" class="muted-text">在来源详情中加入此组。</span></div></div><p v-if="!store.tabGroups.length" class="card-note">将工作资料与待处理收纳区组合在一个面板中，通过标签页或“全部来源”查看。</p></div>
  <UModal v-model:open="createOpen" title="添加桌面内容" description="先选择你想完成的任务。" :ui="{content:'max-w-xl'}"><template #body><div v-if="!kind" class="creation-choices"><button v-for="item in kinds" :key="item.id" class="creation-choice" @click="kind=item.id"><UIcon :name="item.icon"/><span><strong>{{item.name}}</strong><small>{{item.description}}</small></span><UIcon name="i-lucide-chevron-right"/></button></div><div v-else class="form-stack"><div class="info-callout">{{kinds.find(item=>item.id===kind)?.description}}<p v-if="kind==='zone'">目录：桌面\.nestra\{{name||'收纳区名称'}}</p></div><label>显示名称<UInput v-model="name" placeholder="例如：项目资料" class="w-full"/></label><label v-if="kind==='folder'">已有文件夹<div class="flex gap-2"><UInput v-model="path" class="flex-1" placeholder="选择已有目录"/><UButton variant="outline" @click="browse">选择…</UButton></div></label><label v-if="kind==='category'">显示类型<USelect v-model="typeFilter" :items="[...fileFilters]"/></label><div v-if="kind==='group'" class="form-stack"><UCheckbox v-for="source in store.customGroups" :key="source.id" :label="source.name" :model-value="selectedSources.includes(source.id)" @update:model-value="value=>selectedSources=value?[...selectedSources,source.id]:selectedSources.filter(id=>id!==source.id)"/><p class="muted-text">加入新文件组会从原文件组移出，文件保持原位。</p></div><p v-if="error" class="error-text" role="alert">{{error}}</p></div></template><template #footer><UButton variant="ghost" color="neutral" @click="kind?kind='':createOpen=false">{{kind?'返回':'取消'}}</UButton><UButton v-if="kind" :loading="creating" :disabled="!name.trim()||(kind==='folder'&&!path.trim())||(kind==='group'&&!selectedSources.length)" @click="submit">创建</UButton></template></UModal>
  <UModal v-model:open="detailOpen" :title="detail?.name??'来源管理'" description="显示方式与文件存放位置分别管理。"><template #body><div v-if="detail" class="form-stack"><label>名称<div class="flex gap-2"><UInput v-model="detailName" class="flex-1"/><UButton variant="outline" @click="saveName">保存名称</UButton></div></label><label>筛选<USelect :model-value="detail.filter??'all'" :items="[...fileFilters]" @update:model-value="value=>updateGroupView(detail!.id,{filter:value as CustomGroupDefinition['filter']})"/></label><label>加入文件组<USelect :model-value="membership(detail.id)" :items="groupOptions" @update:model-value="value=>assignGroupToTabs(detail!.id,value==='__standalone'?null:value)"/></label><label v-if="detail.mappedPath">拖入策略<USelect :model-value="detail.dropPolicy??'move'" :items="[{label:'只浏览 · 不接收拖入',value:'none'},{label:'接收文件 · 真实移动到此目录',value:'move'}]" @update:model-value="value=>{detail!.dropPolicy=value as 'none'|'move';scheduleSave()}"/></label><p class="muted-text">{{detail.mappedPath??(detail.sourceKind==='category'?'只筛选个人桌面':'桌面\\.nestra\\'+detail.dirName)}}</p><div class="flex gap-2"><UButton variant="outline" @click="locateSurface(surfaceKey(detail.id))">显示并定位</UButton><UButton v-if="detail.mappedPath" variant="outline" @click="repair(detail.id)">重新绑定目录</UButton></div><div class="danger-section"><p>{{sourceFor(detail).kind==='zone'?'解散会先把全部文件放回桌面，失败时保留收纳区。':'移除只删除此视图，原文件不移动、不删除。'}}</p><UButton color="error" variant="soft" @click="async()=>{await removeCustomGroup(detail!.id);if(!store.customGroups.some(g=>g.id===detailId))detailOpen=false}">{{sourceFor(detail).kind==='zone'?'解散收纳区':'移除视图'}}</UButton></div></div></template></UModal>
  <UModal v-model:open="ruleOpen" title="整理预览" description="先查看将移动的文件，再执行本次整理。自动移动未启用。" :ui="{content:'max-w-2xl'}" :dismissible="!executing"><template #body><div class="form-stack"><div class="form-columns"><label>来源<USelect v-model="ruleSource" :items="sourceOptions"/></label><label>目标收纳区<USelect v-model="ruleTarget" :items="targetOptions"/></label><label>文件类型<USelect v-model="ruleFilter" :items="[...fileFilters]"/></label><label>名称包含<UInput v-model="ruleQuery" placeholder="可留空"/></label></div><div class="info-callout">移动目标：桌面\.nestra\{{target?.dirName??'请选择'}}。同名保留两份，失败项留在原位。</div><UButton variant="outline" :disabled="!ruleTarget||ruleTarget===ruleSource||executing" @click="preview">生成本次移动预览</UButton><div class="plan-list"><div v-for="item in plan" :key="item.id" class="plan-row"><strong>{{item.name}}</strong><small>{{item.path}}</small></div></div><div v-if="operationResults.length" class="plan-list"><div v-for="result in operationResults" :key="result.path" class="plan-row" :class="{'error-text':!result.ok}"><strong>{{result.name}} · {{result.ok?'成功':'失败'}}</strong><small>{{result.message}}</small></div></div></div></template><template #footer><UButton variant="ghost" :disabled="executing" @click="ruleOpen=false">关闭</UButton><UButton v-if="operationResults.some(r=>!r.ok)" variant="outline" :loading="executing" @click="execute(true)">重试失败项</UButton><UButton :loading="executing" :disabled="!plan.length||!ruleTarget||operationResults.length>0" @click="execute()">执行本次移动（{{plan.length}} 项）</UButton></template></UModal>
</template>
